import numpy as np

def test_f(b, c, limit=20):
    values = set()
    for a1 in range(-limit, limit+1):
        for a2 in range(-limit, limit+1):
            for a3 in range(-limit, limit+1):
                if len({a1, a2, a3}) < 3:
                    continue
                val = c * (a3**2 - a1**2 - a2**2) + b * (a3 - a1 - a2) - (a3**3 - a1**3 - a2**3)
                values.add(val)
    return values

print(f"b=0, c=0: {test_f(0, 0, 5)}")
