print(f"b=2, c=3: {test_f(2, 3, 5)}")

def check_k1(b, c, limit=20):
    for a1 in range(-limit, limit+1):
        for a2 in range(-limit, limit+1):
            if a1 == a2: continue
            if a1**2 + a1*a2 + a2**2 - b*(a1+a2) - c == 0:
                return True
    return False

print(f"b=2, c=3, k=1: {check_k1(2, 3)}")

